async function jupFetch(request, resultContentType, options) {
	const r = await fetch(request);
	const contentType = r?.headers?.get("content-type");
	if (r?.ok) {
		if (contentType?.includes(resultContentType)) return r;
	}
	if (await handleJsonErrorResponse(r, options)) return null;
	await handleNotJsonResponse(r);
	throw new Error("unhandle fetch error");
}
async function handleJsonErrorResponse(r, options) {
	const contentType = r.headers?.get("content-type");
	if (contentType?.includes("application/json")) {
		consoleError("error in json fetch", r.status, contentType);
		const result = await r.json();
		const message = result?.message ?? result?.error ?? "no message found on fetch error response";
		const error = new Error(message);
		if (options?.onApiError) {
			options.onApiError({
				error: { message },
				status: r.status
			});
			return true;
		} else throw error;
	}
	return false;
}
async function handleNotJsonResponse(r) {
	const contentType = r.headers?.get("content-type");
	const text = await r.text();
	consoleError("error in fetch", r.status, contentType, text);
	if (contentType?.includes("text/html")) {
		const message = load(text)("title").text();
		if (message?.length === 0) throw new Error(`${text.substring(0, 69)}...`);
		throw new Error(message);
	}
}
