async function postRest(endpoint, route, body, options, headers) {
	const fetchRoute = `${endpoint}${route}`;
	const init = {
		method: "post",
		credentials: options?.credentials,
		signal: resolveAbortSignal(options),
		body,
		headers,
		mode: options?.mode
	};
	const r = await jupFetch(new Request(fetchRoute, init), "application/json", options);
	if (r === null) return null;
	if (!r) throw new Error("no response for fetch");
	if (r.ok) return r.json();
	throw new Error("uncatched error in post rest");
}
