//#region src/core/packages/area/area.ts
function getArea2d(points, ratio) {
	const l = points.length;
	let det = 0;
	points = points.concat(points[0]);
	for (let i = 0; i < l; i += 1) {
		const a = ratio * points[i].x * (points[i + 1].y * ratio);
		const b = ratio * points[i].y * (points[i + 1].x * ratio);
		det += a - b;
	}
	return importRound(Math.abs(det) / 2);
}
//#endregion
//#region src/core/packages/area/distance.ts
function lineDistance(point1, point2) {
	let xs = point2.x - point1.x;
	xs = xs * xs;
	let ys = point2.y - point1.y;
	ys = ys * ys;
	return Math.sqrt(xs + ys);
}
//#endregion
//#region src/core/packages/area/perimeter.ts
function getPerimeter(points, ratio) {
	let sumDistance = 0;
	for (let i = 0; i < points.length - 1; i += 1) {
		const p1 = points[i];
		if (i == 0) sumDistance += lineDistance(p1, points[points.length - 1]) * ratio;
		sumDistance += lineDistance(p1, points[i + 1]) * ratio;
	}
	return importRound(Number.parseFloat(sumDistance.toFixed(1)));
}
//#endregion
//#region src/core/packages/area/computeRoomSurfaceFromPoints.helper.ts
/**
* Plan fixtures use centimetres as coordinates.
* Map scale ratio `0.01` → 1 unit = 1 cm → surfaces in m² (Surfy `room.area`).
*/
var FIXTURE_PLAN_CM_TO_M_RATIO = .01;
/** Same calculation as backend `impactRooms` / front `getUpdatedRoom`. */
function computeRoomSurfaceFromPoints(points, ratio = FIXTURE_PLAN_CM_TO_M_RATIO) {
	if (points.length < 3) return {
		area: 0,
		perimeter: 0
	};
	return {
		area: getArea2d([...points], ratio),
		perimeter: getPerimeter([...points], ratio)
	};
}
